/// The file's text: the header, then one line per constant, sorted by name.
fn render(mut constants: Vec<(&'static str, Value)>) -> String {
    constants.sort_by(|a, b| a.0.cmp(b.0));
    let mut out = String::from(HEADER);
    for (name, value) in constants {
        out.push_str(&format!("export const {name} = {value};\n"));
    }
    out
}

#[test]
fn every_name_is_listed_once() {
    let mut names: Vec<&str> = constants().iter().map(|(name, _)| *name).collect();
    let listed = names.len();
    names.sort_unstable();
    names.dedup();
    assert_eq!(names.len(), listed, "a constant is listed twice");
    // Social: friends, presence, challenges, chat (#937, #938, #941)
    assert_eq!(
        // Count verified across features: #936, S7, Duos (#946), SPEC §14 economy (#1298, #1333, #1483, #1339, R1313000, #1301, #1306, R1310000, #1661, R1661001, R1935000, R2101000, R2210000).
        // #2728: four per-step cosmetic bar sizes and four targets in place of COSMETIC_TOKEN_BAR_SIZE and
        // COSMETIC_TOKEN_BAR_TARGET_PACKS (R2728000). #2875: NEWS_TTL_DAYS and five news rewards.
        // #3074: the dev dashboard's seven (R3074000, R3074001, R3074003).
        // #3013: PROFICIENCY_LEVEL_PLAYS and PROFICIENCY_LEVELS (R3013000).
        // #3207: QUEUE_POPULATION_POLL_SECONDS and LIVE_GAME_POLL_SECONDS (R3207000, R3207001).
        // #3212: PACKS_OPEN_ALL_MAX and DECK_SYNC_ITEMS_MAX (R3212000, R3212001).
        // #3213: POST_GAME_FRAME_VERSION (R3213000).
        // #3335: FLEET_TRACK_LEVELS and FLEET_TRACK_XP_DAILY_MAX (R3335001).
        listed,
        87 + 35 + 1 + 1 + 1 + 1 + 6 + 2 + 1 + 1 + 1 + 6 + 6 + 4 + 7 + 2 + 2 + 2 + 1 + 2,
        "the 50 names the client imported from apps/server/src/config.ts, ROOM_CODE_FORMAT (R767), the \
         four USERNAME_* hints (R1432, R1435), the three WS_* heartbeat numbers (R1441), the play \
         telemetry's retention for the privacy policy (R1442), the age screen's and terms' three \
         (R757000, R757001), REPLAY_LIST_PAGE and REPLAY_REQUESTS_PER_MINUTE (R768), with \
         RATING_WINDOW_FULL_AFTER_SECONDS in place of the uncapped window's \
         RATING_WINDOW_UNCAPPED_AFTER_SECONDS (R640001), QUEUE_ENDED_AFTER_READS (R897000), SPEC S7's \
         twelve (#936) with the social poll (SOCIAL_POLL_MS), Duos co-op's eight clocks and ping \
         limits (#946), PLAYER_STATS_BYTES_MAX (R1142000), SPEC §14's thirty-five economy \
         numbers (#1298's, less #1333's CHASE_DROP_RATE, plus #1483's JLORE_GAMES_DAILY_CAP and \
         PRACTICE_SEEDS_OPEN_MAX, less #1339's four rate constants), ECONOMY_LIVE (R1313000), the \
         pack roll's GLOBAL_PACK_NAME (#1301), the cosmetic pack's COSMETIC_PACK_CARD_WEIGHTS \
         (#1306), STARTER_CARDS (R1310000), and #1339's TIER_WEIGHT_TOTAL, CARD_TIER_WEIGHTS, \
         COSMETIC_TIER_WEIGHTS, PACK_FLOORED_SLOT, PACK_FLOOR_RARITY and COSMETIC_PACK_FLOOR_RARITY \
         (R1339000), #1661's GLOBAL_COSMETIC_ROLL_WEIGHT and GLOBAL_COSMETIC_FLOOR_RARITY \
         (R1661001), CI_RUNS_CACHE_TTL_SECONDS (R1935000), RANK_STREAK_FLAME_LENGTH (R2101000), \
         QUEST_REPLACES_PER_DAY (R2210000) and #2728's four per-step cosmetic bar sizes and four \
         targets in place of COSMETIC_TOKEN_BAR_SIZE and COSMETIC_TOKEN_BAR_TARGET_PACKS (R2728000), \
         #2875's NEWS_TTL_DAYS and five NEWS_REWARD_* amounts (R2875001, R2875003), and #2990's four \
         SPECTATOR_EMOTE_* numbers (R2990001, R2990002), and #3074's DEV_JLORE_PER_REQUEST_MAX, \
         DEV_XP_PER_REQUEST_MAX, DEV_RATING_MIN, DEV_RATING_MAX, NEWS_POST_TITLE_MAX_CHARS, \
         NEWS_POST_SUMMARY_MAX_CHARS and NEWS_SUMMARY_MAX_SENTENCES (R3074000, R3074001, R3074003), \
         and #3013's PROFICIENCY_LEVEL_PLAYS and PROFICIENCY_LEVELS (R3013000), and #3207's \
         QUEUE_POPULATION_POLL_SECONDS and LIVE_GAME_POLL_SECONDS (R3207000, R3207001), and #3212's \
         PACKS_OPEN_ALL_MAX and DECK_SYNC_ITEMS_MAX (R3212000, R3212001), and #3213's \
         POST_GAME_FRAME_VERSION (R3213000)"
    );
}

#[test]
fn the_output_is_deterministic() {
    assert_eq!(
        render(constants()),
        render(constants().into_iter().rev().collect())
    );
}

#[test]
fn export_server_config() {
    let text = render(constants());
    let current = std::fs::read_to_string(OUTPUT).unwrap_or_default();
    if current != text {
        if let Some(parent) = std::path::Path::new(OUTPUT).parent() {
            std::fs::create_dir_all(parent).unwrap_or_else(|error| panic!("{}: {error}", parent.display()));
        }
        std::fs::write(OUTPUT, &text).unwrap_or_else(|error| panic!("{OUTPUT}: {error}"));
    }
}

// R1410, R3114000: a shipped set's deck-code offset is its place in the catalog order in thousands,
// read from the set table, so the offsets the client reads stay as they were minted; a set the
// catalog does not order has none.
#[test]
fn r3114000_each_shipped_set_s_offset_is_its_catalog_place_in_thousands() {
    assert_eq!(
        catalog_number_set_offsets(),
        json!({
            "Core": 0,
            "Classic": 1000,
            "Classic+": 2000,
            "Meditative": 3000,
            "Meditative+": 4000,
            "Stinkyscape": 5000,
            "Training Grounds": 6000,
        })
    );
    for set in [SetName::Boss, SetName::BossX] {
        assert_eq!(c::catalog_number_set_offset(set), None, "{set:?}");
    }
}

// R3535000: the held Stinkyscape+ set keeps its catalog place (offset 7000) for the day it ships,
// but no deck holds it yet, so the client is not given an offset for it (CLAUDE.md rule 3).
#[test]
fn r3535000_the_held_stinkyscape_plus_set_keeps_its_offset_but_is_not_exported() {
    assert_eq!(c::catalog_number_set_offset(SetName::StinkyscapePlus), Some(7000));
    assert!(
        !catalog_number_set_offsets()
            .as_object()
            .expect("offsets are a record")
            .contains_key("Stinkyscape+"),
        "a held set is in no deck"
    );
}

/// The exported value of one name.
fn exported(name: &str) -> Value {
    constants()
        .into_iter()
        .find(|(listed, _)| *listed == name)
        .unwrap_or_else(|| panic!("{name} is not exported"))
        .1
}

// R3207000: the lobby's wait reads the queue readout every QUEUE_POPULATION_POLL_SECONDS, so each
// read counts anew (past the readout's kept answer), and the client reads the number from here.
#[test]
fn r3207000_the_population_poll_is_exported_and_outlasts_the_kept_readout() {
    const _: () = assert!(c::QUEUE_POPULATION_POLL_SECONDS >= 30 && c::QUEUE_POPULATION_POLL_SECONDS <= 60);
    const _: () = assert!(c::QUEUE_POPULATION_POLL_SECONDS > c::QUEUE_READOUT_CACHE_TTL_SECONDS);
    assert_eq!(
        exported("QUEUE_POPULATION_POLL_SECONDS"),
        json!(c::QUEUE_POPULATION_POLL_SECONDS)
    );
}

// R3207001: the live-game banner re-reads the account every LIVE_GAME_POLL_SECONDS, slower than the
// queue follow's SERIES_POLL_SECONDS, and the client reads the number from here.
#[test]
fn r3207001_the_live_game_poll_is_exported_and_slower_than_the_queues() {
    const _: () = assert!(c::LIVE_GAME_POLL_SECONDS >= 10 && c::LIVE_GAME_POLL_SECONDS <= 15);
    const _: () = assert!(c::LIVE_GAME_POLL_SECONDS > c::SERIES_POLL_SECONDS);
    assert_eq!(
        exported("LIVE_GAME_POLL_SECONDS"),
        json!(c::LIVE_GAME_POLL_SECONDS)
    );
}
